import json

class Tarea:
    def __init__(self, id_tarea, titulo):
        self.id_tarea = id_tarea
        self.titulo = titulo
        self.completada = False

    def to_dict(self):
        return {'id': self.id_tarea, 'titulo': self.titulo, 'completada': self.completada}

class GestorTareas:
    def __init__(self):
        self.tareas = []

    def agregar(self, titulo):
        nueva = Tarea(len(self.tareas) + 1, titulo)
        self.tareas.append(nueva)
        return nueva

    def guardar_json(self, ruta):
        datos = [t.to_dict() for t in self.tareas]
        with open(ruta, 'w', encoding='utf-8') as f:
            json.dump(datos, f, indent=2)

gestor = GestorTareas()
gestor.agregar('Completar curso de Python con NVDA')
gestor.guardar_json('tareas_final.json')
print(f'Sistema integrado activo: {len(gestor.tareas)} tareas gestionadas con éxito.')

class Tarea:
    def __init__(self, titulo):
        self.titulo = titulo
        self.completada = False

    def completar(self):
        self.completada = True

t = Tarea('Graduación en Python')
t.completar()
print(f'Estado final de la tarea: {t.titulo} -> Completada: {t.completada}')
